#include <bits/stdc++.h>
#define fi first
#define se second
using namespace std;

const int MAX = 5500;
const long long INF = 1E9 + 7;

int n, m, k, c, d;
int u, v, max_flow, s = MAX - 2, t = MAX - 1, flow = 0, parent[MAX];
long long total_cost = 0, dist[MAX];
priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

struct Edge {
    int v, c;
    int index, capacity;
};
vector<Edge> graph[MAX];

void addEdge(int u, int v, int cost, int cap) {
    int sizeU = graph[u].size(), sizeV = graph[v].size();
    graph[u].push_back({v, cost, sizeV, cap});
    graph[v].push_back({u, -cost, sizeU, 0});
}

void computeShortestPath() {
    fill(dist, dist + MAX, INF);
    pq.push({dist[s] = 0, s});
    while (!pq.empty()) {
        auto [currDist, node] = pq.top();
        pq.pop();
        if (currDist > dist[node]) continue;
        for (auto &edge : graph[node]) {
            if (edge.capacity > 0 && dist[edge.v] > currDist + edge.c) {
                parent[edge.v] = edge.index;
                dist[edge.v] = currDist + edge.c;
                pq.push({dist[edge.v], edge.v});
            }
        }
    }
}

void augmentFlow() {
    int flowIncrement = k, v = t;
    while (v != s) {
        int u = graph[v][parent[v]].v;
        int ind = graph[v][parent[v]].index;
        flowIncrement = min(flowIncrement, graph[u][ind].capacity);
        v = u;
    }
    flow += flowIncrement;
    total_cost += (long long)flowIncrement * dist[t];
    v = t;
    while (v != s) {
        int u = graph[v][parent[v]].v;
        int ind = graph[v][parent[v]].index;
        graph[v][parent[v]].capacity += flowIncrement;
        graph[u][ind].capacity -= flowIncrement;
        v = u;
    }
}

int nodeId(int u, int t) {
    return u + t * n;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> k >> c >> d;
    max_flow = n + k;
    for (int i = 0; i < k; i++) {
        cin >> u;
        addEdge(s, nodeId(u, 0), 0, 1);
    }
    for (int i = 0; i <= max_flow; i++)
        addEdge(nodeId(1, i), t, c * i, k);
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < max_flow; j++)
            addEdge(nodeId(i, j), nodeId(i, j + 1), 0, k);
    for (int i = 0; i < m; i++) {
        cin >> u >> v;
        for (int j = 0; j < k; j++) {
            for (int l = 0; l < max_flow; l++) {
                addEdge(nodeId(u, l), nodeId(v, l + 1), d * (2 * j + 1), 1);
                addEdge(nodeId(v, l), nodeId(u, l + 1), d * (2 * j + 1), 1);
            }
        }
    }
    while (flow < k) {
        computeShortestPath();
        augmentFlow();
    }
    cout << total_cost;
}
